from pathlib import Path

path = Path('static/src/App.tsx')
text = path.read_text()

old_header = '''                        <div className="row">\n                          <div>\n                            <h2>Workflow Migration Engine</h2>\n                            <p className="hint">v6.0 separates source evidence, a buildable Jira workflow model, and manual-review items. It does not invent missing Ivanti workflow logic.</p>\n                          </div>\n                          <label className="compactLabel">Show<select value={workflowFilter} onChange={(event) => setWorkflowFilter(event.target.value as 'all' | WorkflowCategory)}><option value="all">All evidence</option>{Object.entries(CATEGORY_LABELS).map(([value, label]) => <option key={value} value={value}>{label}s</option>)}</select></label>\n                        </div>\n\n                        <div className="reportMetrics">\n                          <div><strong>{activeService.analysis.workflowMigration.statuses.length}</strong><span>Explicit statuses</span></div>\n                          <div><strong>{activeService.analysis.workflowMigration.transitions.filter((item) => item.fromStatus && item.toStatus).length}</strong><span>Buildable transitions</span></div>\n                          <div><strong>{activeService.analysis.workflowMigration.approvals.length}</strong><span>Approvals</span></div>\n                          <div><strong>{activeService.analysis.workflowMigration.reviewItems.length}</strong><span>Review items</span></div>\n                          <div><strong>{activeService.analysis.workflowMigration.confidence}%</strong><span>Source confidence</span></div>\n                        </div>\n'''

new_header = '''                        {(() => {\n                          const orchestrationSource = (activeService.analysis.workflowItems ?? []).some((item) => /all\\s*tasks?\\s*complete|servicedesk|source defect|active directory|office 365|harvest|assets|pbx/i.test(String(item.label ?? '')));\n                          const workflowItems = activeService.analysis.workflowItems ?? [];\n                          const taskCount = workflowItems.filter((item) => item.category === 'task').length;\n                          const gateCount = workflowItems.filter((item) => item.category === 'condition' && /all\\s*tasks?\\s*complete/i.test(String(item.label ?? ''))).length;\n                          const branchCount = workflowItems.filter((item) => item.category === 'condition' && !/all\\s*tasks?\\s*complete|source defect/i.test(String(item.label ?? ''))).length;\n                          const actionCount = workflowItems.filter((item) => ['activity','notification'].includes(item.category) && !/new scenario/i.test(String(item.label ?? ''))).length;\n                          const defectCount = workflowItems.filter((item) => /source defect/i.test(String(item.label ?? ''))).length;\n                          return <>\n                            <div className="row">\n                              <div>\n                                <h2>{orchestrationSource ? 'Ivanti Workflow Orchestration Migration' : 'Workflow Migration Engine'}</h2>\n                                <p className="hint">{orchestrationSource ? 'This source is an orchestration graph. Jira fulfilment tasks, gates, branches and actions are modelled directly without inventing parent statuses.' : 'Separates source evidence, a buildable Jira workflow model, and manual-review items. It does not invent missing Ivanti workflow logic.'}</p>\n                              </div>\n                              <label className="compactLabel">Show<select value={workflowFilter} onChange={(event) => setWorkflowFilter(event.target.value as 'all' | WorkflowCategory)}><option value="all">All evidence</option>{Object.entries(CATEGORY_LABELS).map(([value, label]) => <option key={value} value={value}>{label}s</option>)}</select></label>\n                            </div>\n                            <div className="reportMetrics">\n                              {orchestrationSource ? <>\n                                <div><strong>{taskCount}</strong><span>Fulfilment tasks</span></div>\n                                <div><strong>{gateCount}</strong><span>Joins / gates</span></div>\n                                <div><strong>{branchCount}</strong><span>Branches</span></div>\n                                <div><strong>{actionCount}</strong><span>Actions</span></div>\n                                <div><strong>{defectCount}</strong><span>Source defects</span></div>\n                              </> : <>\n                                <div><strong>{activeService.analysis.workflowMigration.statuses.length}</strong><span>Explicit statuses</span></div>\n                                <div><strong>{activeService.analysis.workflowMigration.transitions.filter((item) => item.fromStatus && item.toStatus).length}</strong><span>Buildable transitions</span></div>\n                                <div><strong>{activeService.analysis.workflowMigration.approvals.length}</strong><span>Approvals</span></div>\n                                <div><strong>{activeService.analysis.workflowMigration.reviewItems.length}</strong><span>Review items</span></div>\n                                <div><strong>{activeService.analysis.workflowMigration.confidence}%</strong><span>Source confidence</span></div>\n                              </>}\n                            </div>\n                          </>;\n                        })()}\n'''

if old_header not in text:
    raise SystemExit('Expected workflow header/metrics block not found')
text = text.replace(old_header, new_header, 1)

unsafe_cards = '''                          <article className="buildCard liveStructure">\n                            <div>\n                              <strong>Jira issue type and workflow</strong>\n                              <p>Create or reuse an issue type, workflow, statuses, transitions and an inactive workflow scheme.</p>\n                            </div>\n                            <button disabled={structureBusy} onClick={() => createJiraStructure(activeService)}>\n                              {structureBusy ? 'Creating…' : 'Create Jira structure'}\n                            </button>\n                          </article>\n                          <article className="buildCard liveStructure">\n                            <div>\n                              <strong>Activate in target project</strong>\n                              <p>Assign the created workflow scheme to the company-managed project selected in Settings. Jira only allows direct assignment when the project has no issues.</p>\n                            </div>\n                            <button\n                              disabled={activationBusy || !structureResults[activeService.id]?.workflowSchemeId || !migration.targetProjectId}\n                              onClick={() => assignWorkflowScheme(activeService)}\n                            >\n                              {activationBusy ? 'Assigning…' : 'Assign to target project'}\n                            </button>\n                          </article>\n                          <article className="buildCard liveStructure">\n                            <div><strong>Jira screens</strong><p>Create or reuse Create, Edit and View screens, add the migrated fields, and build the screen schemes.</p></div>\n                            <button disabled={screenBusy || !structureResults[activeService.id]?.issueTypeId} onClick={() => createScreenStructure(activeService)}>{screenBusy ? 'Creating…' : 'Create Jira screens'}</button>\n                          </article>\n                          <article className="buildCard liveStructure">\n                            <div><strong>Activate screens in target project</strong><p>Assign the issue type screen scheme to the company-managed project selected in Settings.</p></div>\n                            <button disabled={screenActivationBusy || !screenResults[activeService.id]?.issueTypeScreenSchemeId || !migration.targetProjectId} onClick={() => assignScreenScheme(activeService)}>{screenActivationBusy ? 'Assigning…' : 'Assign screen scheme'}</button>\n                          </article>\n'''

safe_cards = '''                          {(() => {\n                            const orchestrationSource = (activeService.analysis.workflowItems ?? []).some((item) => /all\\s*tasks?\\s*complete|servicedesk|source defect|active directory|office 365|harvest|assets|pbx/i.test(String(item.label ?? '')));\n                            if (!orchestrationSource) return <>\n                              <article className="buildCard liveStructure"><div><strong>Jira issue type and workflow</strong><p>Create or reuse an issue type, workflow, statuses, transitions and an inactive workflow scheme.</p></div><button disabled={structureBusy} onClick={() => createJiraStructure(activeService)}>{structureBusy ? 'Creating…' : 'Create Jira structure'}</button></article>\n                              <article className="buildCard liveStructure"><div><strong>Activate in target project</strong><p>Assign the created workflow scheme to the company-managed project selected in Settings.</p></div><button disabled={activationBusy || !structureResults[activeService.id]?.workflowSchemeId || !migration.targetProjectId} onClick={() => assignWorkflowScheme(activeService)}>{activationBusy ? 'Assigning…' : 'Assign to target project'}</button></article>\n                              <article className="buildCard liveStructure"><div><strong>Jira screens</strong><p>Create or reuse Create, Edit and View screens, add the migrated fields, and build the screen schemes.</p></div><button disabled={screenBusy || !structureResults[activeService.id]?.issueTypeId} onClick={() => createScreenStructure(activeService)}>{screenBusy ? 'Creating…' : 'Create Jira screens'}</button></article>\n                              <article className="buildCard liveStructure"><div><strong>Activate screens in target project</strong><p>Assign the issue type screen scheme to the company-managed project selected in Settings.</p></div><button disabled={screenActivationBusy || !screenResults[activeService.id]?.issueTypeScreenSchemeId || !migration.targetProjectId} onClick={() => assignScreenScheme(activeService)}>{screenActivationBusy ? 'Assigning…' : 'Assign screen scheme'}</button></article>\n                            </>;\n                            return <>\n                              <article className="buildCard ready"><div><strong>Fulfilment implementation pack</strong><p>Uses the recovered Ivanti orchestration model: two fulfilment waves, two gates, Assets, the ServiceDesk → PBX branch, completion logic and source-defect quarantine.</p></div><button className="secondary" onClick={() => exportServiceBlueprint(activeService)}>Export implementation pack</button></article>\n                              <article className="buildCard blueprint"><div><strong>Safe orchestration boundary</strong><p>This source does not require a new Jira parent workflow, workflow scheme or screen scheme. Those controls are intentionally hidden to avoid destructive project-level configuration changes.</p></div><span className="structureState created">protected</span></article>\n                            </>;\n                          })()}\n'''

if unsafe_cards not in text:
    raise SystemExit('Expected unsafe create-tab cards not found')
text = text.replace(unsafe_cards, safe_cards, 1)

path.write_text(text)
print('Applied orchestration-first safe UI patch')
